{"content": "def upgrade(record):
    """Convert a v1 record to v2 format.

    v1 format:  {"id", "name", "remote": "yes"/"no"}
    v2 format:  {"version": 2, "id", "title", "work_mode": "remote"/"office"/"unknown"}

    - name becomes title
    - remote yes -> remote, no -> office, missing -> unknown
    - any other remote value raises ValueError
    - never modifies the input; returns a new dict
    - v2 records returned as an equal copy (idempotent)
    """
    # If already v2, return a copy (idempotent)
    if record.get('version') == 2:
        return {k: v for k, v in record.items()}

    # v1 -> v2 conversion, never modify input
    new = dict(record)
    new['title'] = new.pop('name')

    remote = new.get('remote')
    if remote == 'yes':
        new['work_mode'] = 'remote'
    elif remote == 'no':
        new['work_mode'] = 'office'
    elif remote is None:
        new['work_mode'] = 'unknown'
    else:
        raise ValueError(f"Invalid remote value: {remote!r}")

    new['version'] = 2
    return new"}

